"""P1a: generated bytes are not a Git blob or Native observation."""

from dataclasses import replace
from hashlib import sha256

import pytest

from physics_harness.code.diagnostics import (
    FactBatch, GitSourceProvider, GraphAssembler, ScanRequest, run_scan,
)
from physics_harness.code.diagnostics.providers.generated_input import (
    GeneratedInputIdentity, collect_generated_input,
)
from physics_harness.code.verification.consistency import verify_generated_artifact


HIT = b"[Kernels]\n  [./test]\n    type = MyKernel\n    variable = u\n    rho = rho_const\n  [../]\n[]\n"
CPP = 'registerMooseObject("PhysicsApp", MyKernel);\n'


def fixture(git_factory, content=HIT):
    root, revision = git_factory({
        "src/generate.py": "def generate():\n    return 'generated.i'\n",
        "src/MyKernel.C": CPP,
    })
    request = ScanRequest("example/repo", revision, ("src/*",),
                          collectors=("python_ast", "cpp"))
    provider = GitSourceProvider(root)
    producer = provider.read_at_revision(revision, "src/generate.py")
    identity = GeneratedInputIdentity(
        request.repository, revision, producer.record.path,
        producer.record.blob_sha, 10, 1, 20, "results/generated.i",
        sha256(content).hexdigest(), sha256(b"configuration").hexdigest(),
    )
    return request, provider, identity


def collect(request, provider, identity, content=HIT, expected=None):
    return collect_generated_input(
        request, provider, expected=expected or identity, receipt=identity,
        content=content,
    )


def assemble(request, provider, *generated):
    source = run_scan(request, provider)
    graph = source.graph
    base = FactBatch(nodes=graph.nodes, edges=graph.edges, evidence=graph.evidence,
                     unresolved=graph.scope.unresolved)
    return GraphAssembler().assemble(
        request, (base, *(x.batch for x in generated)), source.receipt)


def test_generated_types_join_existing_factory_but_not_runtime(git_factory):
    request, provider, identity = fixture(git_factory)
    result = collect(request, provider, identity)
    assert result.status == "PARTIAL"
    full = assemble(request, provider, result)
    assert full.status == "PARTIAL"
    assert full.verification.status == "UNVERIFIED"
    assert not full.verification.failures
    assert all(f.path.startswith("src/") for f in full.receipt.files)
    nodes = full.graph.nodes_by_id()
    types = [n for n in nodes.values() if n.kind == "moose_type"]
    assert len(types) == 1 and types[0].name == "MyKernel"
    edge = next(e for e in full.graph.edges
                if e.relation == "GENERATED_DECLARES_TYPE_USE")
    assert edge.target_id == types[0].id
    block = nodes[edge.source_id]
    assert block.kind == "generated_moose_input_block"
    assert block.attributes["block_path"] == "Kernels/test"
    assert ("rho", "rho_const") in block.attributes["parameter_values"]
    assert ("variable", "u") in block.attributes["parameter_values"]
    assert block.location is None
    assert not any(e.observation_status == "RUNTIME_OBSERVED"
                   for e in full.graph.evidence)
    assert not full.graph.claims
    assert any(e.relation == "GENERATED_INPUT_CANDIDATE"
               for e in full.graph.edges)
    assert not any(e.source_ref.startswith("_generated_input_parser/")
                   for e in full.graph.evidence)


@pytest.mark.parametrize("field,value", [
    ("attempt", 2), ("run_id", 11), ("artifact_id", 21),
    ("source_sha", "a" * 40), ("producer_blob_sha", "b" * 40),
    ("invocation_sha256", "c" * 64), ("artifact_sha256", "d" * 64),
    ("artifact_path", "different.i"),
])
def test_expected_identity_rejects_mismatched_receipt(git_factory, field, value):
    request, provider, identity = fixture(git_factory)
    with pytest.raises(ValueError, match="GENERATED_RECEIPT_IDENTITY_MISMATCH"):
        collect(request, provider, replace(identity, **{field: value}),
                expected=identity)


def test_same_claim_cannot_bypass_actual_git_and_bytes(git_factory):
    request, provider, identity = fixture(git_factory)
    with pytest.raises(ValueError, match="GENERATED_CONTENT_DIGEST_MISMATCH"):
        collect(request, provider, identity, HIT + b"# tamper")
    with pytest.raises(ValueError, match="GENERATED_PRODUCER_BLOB_MISMATCH"):
        collect(request, provider, replace(identity, producer_blob_sha="b" * 40))
    with pytest.raises(ValueError, match="GENERATED_SOURCE_SCOPE_MISMATCH"):
        collect(request, provider, replace(identity, source_sha="a" * 40))


def test_dynamic_include_and_type_remain_unresolved(git_factory):
    content = b"!include other.i\n[Kernels]\n [./test]\n type = ${KERNEL}\n [../]\n[]\n"
    request, provider, identity = fixture(git_factory, content)
    result = assemble(request, provider, collect(request, provider, identity, content))
    assert result.status == "PARTIAL"
    assert result.verification.status == "UNVERIFIED"
    assert not result.verification.failures
    assert any(e.relation == "GENERATED_DYNAMIC_TYPE_CANDIDATE"
               for e in result.graph.edges)
    assert any(e.observation_status == "UNRESOLVED"
               and e.kind == "GENERATED_INPUT" for e in result.graph.evidence)


def test_attempts_are_separate_artifact_occurrences(git_factory):
    request, provider, identity = fixture(git_factory)
    first = collect(request, provider, identity)
    second = collect(request, provider, replace(identity, attempt=2))
    combined = assemble(request, provider, first, second)
    assert len([n for n in combined.graph.nodes
                if n.kind == "generated_moose_input"]) == 2
    assert len([n for n in combined.graph.nodes if n.kind == "moose_type"]) == 1
    assert not combined.verification.failures


def test_artifact_provenance_tamper_fails_verification(git_factory):
    request, provider, identity = fixture(git_factory)
    result = assemble(request, provider, collect(request, provider, identity))
    ev = next(e for e in result.graph.evidence
              if e.kind == "GENERATED_INPUT" and e.attributes["line"] > 0)
    bad = replace(ev, source_ref=identity.reference(999))
    graph = replace(result.graph, evidence=tuple(
        bad if e.id == ev.id else e for e in result.graph.evidence))
    verification = verify_generated_artifact(graph, result.receipt)
    assert verification.status == "FAILED"
    assert any(x.startswith("GENERATED_INPUT_PROVENANCE_INVALID:")
               for x in verification.failures)


def test_budget_and_out_of_scope_fail_closed(git_factory):
    from physics_harness.code.diagnostics import ScanBudget
    request, provider, identity = fixture(git_factory)
    with pytest.raises(ValueError, match="GENERATED_BYTE_BUDGET_EXCEEDED"):
        collect(replace(request, budget=ScanBudget(max_bytes=1)),
                provider, identity)
    with pytest.raises(ValueError, match="GENERATED_PRODUCER_OUT_OF_SCOPE"):
        collect(replace(request, includes=("src/*.C",)), provider, identity)
